            function initSliders() {
                const win = editor.Canvas.getWindow();
                const doc = editor.Canvas.getDocument();

                doc.querySelectorAll('.banner-classic-active2').forEach((el) => {
                    if (el.swiper) el.swiper.destroy(true, true);

                    new win.Swiper(el, {
                        loop: true,
                        slidesPerView: 1,
                        navigation: {
                            nextEl: '.loginet-banner-arrow-box2 .slider-next',
                            prevEl: '.loginet-banner-arrow-box2 .slider-prev',
                        }
                    });
                });
            }

            editor.on('load', initSliders);
            editor.on('component:update', initSliders);
            editor.on('component:add', initSliders);
